{
  "name": "llc_conn_start",
  "confidence": "medium",
  "docstring": "Prepares a BLE link-layer connection event by configuring RF/channel descriptors, calibration state, and the controller context, then marks the event as started.",
  "subsystem": "ble",
  "var_renames": {
    "a1": "conn",
    "v3": "src_params",
    "v10": "rf_channel_cfg",
    "v11": "active_ctx",
    "v6": "cal_param",
    "v12": "rf_ctrl_word0",
    "v13": "rf_ctrl_word1"
  },
  "struct_hints": [
    {
      "offset": 72,
      "meaning": "u64 pair of pointers to event descriptor/context and active link-layer state"
    },
    {
      "offset": 44,
      "meaning": "pointer to source LL/TX descriptor parameters copied into the event descriptor"
    },
    {
      "offset": 29,
      "meaning": "u8 RF channel index used to select a per-channel configuration/calibration entry"
    },
    {
      "offset": 30,
      "meaning": "u16 link-layer flags; bit 0x2000 selects the RF configuration path"
    },
    {
      "offset": 76,
      "meaning": "alternate active context pointer used when the RF table entry is unavailable"
    },
    {
      "offset": 82,
      "meaning": "u16 controller state flags; modified with 0x0006 during event start"
    }
  ]
}
